cards.example:
# bash: упадёт при повторе
useradd deploy && apt install -y nginx

# ansible: сколько угодно раз
- user: { name: deploy, state: present }
- apt:  { name: nginx, state: present }

- hosts: web
  serial: 2
  max_fail_percentage: 25
  tasks:
    - name: вывести из балансировки
      command: /usr/local/bin/lb-drain {{ inventory_hostname }}
    - include_role: { name: app_deploy }
    - command: /usr/local/bin/lb-enable {{ inventory_hostname }}
